    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amt, uint256 wamt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amt)); require(amt <= 1000000000000000000000000000000);
        require(amt > 0);
        require(address(this).balance >= amt);
        c.deposit{value: amt}(); if (__ESBMC_reverted()) return;
        uint256 contractBal = address(c).balance;
        require(wamt > amt);
        bool reverted;
        c.withdraw(wamt); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && address(c).balance == contractBal);
    }

    receive() external payable {}
}

