// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 amt, uint256 wamt) internal {
        amt = bound(amt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amt > 0);
        vm.assume(address(this).balance >= amt);
        try c.deposit{value: amt}() {} catch { return; }
        uint256 contractBal = address(c).balance;
        vm.assume(wamt > amt);
        bool reverted;
        try c.withdraw(wamt) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && address(c).balance == contractBal);
    }

    function testFuzz_run(uint256 amt, uint256 wamt) public {
        _run(amt, wamt);
    }

    receive() external payable {}
}
